import json
from pathlib import Path
R={}
def resource(name,typ,props,retain=False):
 R[name]={'Type':typ,'Properties':props}
 if retain:R[name].update({'DeletionPolicy':'Retain','UpdateReplacePolicy':'Retain'})
def ref(x):return {'Ref':x}
def attr(x,y):return {'Fn::GetAtt':[x,y]}
def sub(x):return {'Fn::Sub':x}
resource('Data','AWS::DynamoDB::Table',{'BillingMode':'PAY_PER_REQUEST','AttributeDefinitions':[{'AttributeName':'pk','AttributeType':'S'}],'KeySchema':[{'AttributeName':'pk','KeyType':'HASH'}],'SSESpecification':{'SSEEnabled':True},'PointInTimeRecoverySpecification':{'PointInTimeRecoveryEnabled':True},'TimeToLiveSpecification':{'AttributeName':'expires','Enabled':True},'Tags':[{'Key':'Project','Value':'Welvia'}]},True)
resource('Assets','AWS::S3::Bucket',{'PublicAccessBlockConfiguration':{'BlockPublicAcls':True,'BlockPublicPolicy':True,'IgnorePublicAcls':True,'RestrictPublicBuckets':True},'BucketEncryption':{'ServerSideEncryptionConfiguration':[{'ServerSideEncryptionByDefault':{'SSEAlgorithm':'AES256'}}]},'VersioningConfiguration':{'Status':'Enabled'},'Tags':[{'Key':'Project','Value':'Welvia'}]},True)
resource('Logs','AWS::Logs::LogGroup',{'LogGroupName':sub('/aws/lambda/${AWS::StackName}-api'),'RetentionInDays':14},True)
resource('RuntimeRole','AWS::IAM::Role',{'AssumeRolePolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'lambda.amazonaws.com'},'Action':'sts:AssumeRole'}]},'Policies':[{'PolicyName':'WelviaDataAndLogs','PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':['dynamodb:GetItem','dynamodb:PutItem','dynamodb:UpdateItem'],'Resource':attr('Data','Arn')},{'Effect':'Allow','Action':['logs:CreateLogStream','logs:PutLogEvents'],'Resource':attr('Logs','Arn')}]}}]})
resource('ApiFunction','AWS::Lambda::Function',{'FunctionName':sub('${AWS::StackName}-api'),'Runtime':'python3.12','Handler':'index.handler','Role':attr('RuntimeRole','Arn'),'Timeout':15,'MemorySize':256,'ReservedConcurrentExecutions':5,'Environment':{'Variables':{'TABLE_NAME':ref('Data'),'SITE_URL':'https://welvia.natemitchcook.com'}},'Code':{'ZipFile':Path('backend/index.py').read_text()},'Tags':[{'Key':'Project','Value':'Welvia'}]})
R['ApiFunction']['DependsOn']='Logs'
resource('Api','AWS::ApiGatewayV2::Api',{'Name':sub('${AWS::StackName}-api'),'ProtocolType':'HTTP'})
resource('Integration','AWS::ApiGatewayV2::Integration',{'ApiId':ref('Api'),'IntegrationType':'AWS_PROXY','IntegrationUri':attr('ApiFunction','Arn'),'PayloadFormatVersion':'2.0'})
resource('Route','AWS::ApiGatewayV2::Route',{'ApiId':ref('Api'),'RouteKey':'ANY /api/{proxy+}','Target':{'Fn::Join':['/', ['integrations',ref('Integration')]]}})
resource('Stage','AWS::ApiGatewayV2::Stage',{'ApiId':ref('Api'),'StageName':'$default','AutoDeploy':True,'DefaultRouteSettings':{'ThrottlingBurstLimit':10,'ThrottlingRateLimit':5}})
resource('InvokePermission','AWS::Lambda::Permission',{'FunctionName':ref('ApiFunction'),'Action':'lambda:InvokeFunction','Principal':'apigateway.amazonaws.com','SourceArn':sub('arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${Api}/*/*/api/*')})
resource('OAC','AWS::CloudFront::OriginAccessControl',{'OriginAccessControlConfig':{'Name':sub('${AWS::StackName}-assets'),'OriginAccessControlOriginType':'s3','SigningBehavior':'always','SigningProtocol':'sigv4'}})
resource('CDN','AWS::CloudFront::Distribution',{'DistributionConfig':{'Enabled':True,'Comment':'Welvia isolated pilot','Aliases':['welvia.natemitchcook.com'],'DefaultRootObject':'index.html','PriceClass':'PriceClass_100','HttpVersion':'http2','IPV6Enabled':True,'ViewerCertificate':{'AcmCertificateArn':'arn:aws:acm:us-east-1:589005473076:certificate/e7feaff6-4b0d-449b-939c-35587b744fd5','SslSupportMethod':'sni-only','MinimumProtocolVersion':'TLSv1.2_2021'},'Origins':[{'Id':'assets','DomainName':attr('Assets','RegionalDomainName'),'S3OriginConfig':{'OriginAccessIdentity':''},'OriginAccessControlId':ref('OAC')},{'Id':'api','DomainName':sub('${Api}.execute-api.${AWS::Region}.amazonaws.com'),'CustomOriginConfig':{'OriginProtocolPolicy':'https-only','OriginSSLProtocols':['TLSv1.2']}}],'DefaultCacheBehavior':{'TargetOriginId':'assets','ViewerProtocolPolicy':'redirect-to-https','AllowedMethods':['GET','HEAD','OPTIONS'],'CachedMethods':['GET','HEAD'],'Compress':True,'CachePolicyId':'658327ea-f89d-4fab-a63d-7e88639e58f6'},'CacheBehaviors':[{'PathPattern':'/api/*','TargetOriginId':'api','ViewerProtocolPolicy':'https-only','AllowedMethods':['GET','HEAD','OPTIONS','PUT','POST','PATCH','DELETE'],'CachedMethods':['GET','HEAD'],'Compress':True,'CachePolicyId':'4135ea2d-6df8-44a3-9df3-4b5a84be39ad','OriginRequestPolicyId':'b689b0a8-53d0-40ab-baf2-68738e2966ac'}]},'Tags':[{'Key':'Project','Value':'Welvia'}]})
resource('AssetsPolicy','AWS::S3::BucketPolicy',{'Bucket':ref('Assets'),'PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Service':'cloudfront.amazonaws.com'},'Action':'s3:GetObject','Resource':sub('${Assets.Arn}/*'),'Condition':{'StringEquals':{'AWS:SourceArn':sub('arn:${AWS::Partition}:cloudfront::${AWS::AccountId}:distribution/${CDN}')}}}]}})
resource('DNS','AWS::Route53::RecordSetGroup',{'HostedZoneId':'Z2UVKF8RP48AH','RecordSets':[{'Name':'welvia.natemitchcook.com.','Type':typ,'AliasTarget':{'DNSName':attr('CDN','DomainName'),'HostedZoneId':'Z2FDTNDATAQYW2','EvaluateTargetHealth':False}} for typ in ['A','AAAA']]})
resource('GitHubDeployRole','AWS::IAM::Role',{'RoleName':sub('${AWS::StackName}-github-deploy'),'AssumeRolePolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Principal':{'Federated':sub('arn:${AWS::Partition}:iam::${AWS::AccountId}:oidc-provider/token.actions.githubusercontent.com')},'Action':'sts:AssumeRoleWithWebIdentity','Condition':{'StringEquals':{'token.actions.githubusercontent.com:aud':'sts.amazonaws.com','token.actions.githubusercontent.com:sub':'repo:natemitchcook/personal-site:ref:refs/heads/main'}}}]},'Policies':[{'PolicyName':'DeployWelviaOnly','PolicyDocument':{'Version':'2012-10-17','Statement':[{'Effect':'Allow','Action':['s3:ListBucket'],'Resource':attr('Assets','Arn')},{'Effect':'Allow','Action':['s3:GetObject','s3:PutObject','s3:DeleteObject'],'Resource':sub('${Assets.Arn}/*')},{'Effect':'Allow','Action':['lambda:UpdateFunctionCode','lambda:GetFunctionConfiguration'],'Resource':attr('ApiFunction','Arn')},{'Effect':'Allow','Action':['cloudfront:CreateInvalidation'],'Resource':sub('arn:${AWS::Partition}:cloudfront::${AWS::AccountId}:distribution/${CDN}')},{'Effect':'Allow','Action':['cloudformation:DescribeStacks'],'Resource':ref('AWS::StackId')}]}}]})
T={'AWSTemplateFormatVersion':'2010-09-09','Description':'Welvia isolated SurveyJS pilot. No external messages or payment actions.','Resources':R,'Outputs':{k:{'Value':v} for k,v in {'Bucket':ref('Assets'),'Table':ref('Data'),'Function':ref('ApiFunction'),'ApiUrl':attr('Api','ApiEndpoint'),'DistributionId':ref('CDN'),'SiteUrl':'https://welvia.natemitchcook.com','DeployRoleArn':attr('GitHubDeployRole','Arn')}.items()}}
Path('infrastructure.json').write_text(json.dumps(T,indent=2)+'\n')
